import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


def spans_of(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    hours = parse_span("08:00-18:00")

    def test_gap_between_two_spans(self):
        worked = spans_of("08:00-12:00", "13:00-18:00")
        self.assertEqual(find_gaps(worked, self.hours), ["gap 12:00-13:00 (60 min)"])

    def test_no_gaps_when_fully_covered(self):
        worked = spans_of("08:00-13:00", "12:00-18:00")
        self.assertEqual(find_gaps(worked, self.hours), [])

    def test_touching_spans_leave_no_gap(self):
        worked = spans_of("08:00-12:00", "12:00-18:00")
        self.assertEqual(find_gaps(worked, self.hours), [])

    def test_gaps_at_both_ends(self):
        worked = spans_of("09:00-17:00")
        self.assertEqual(
            find_gaps(worked, self.hours),
            ["gap 08:00-09:00 (60 min)", "gap 17:00-18:00 (60 min)"]
        )

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(find_gaps([], self.hours), ["gap 08:00-18:00 (600 min)"])

    def test_unsorted_and_overlapping_input(self):
        worked = spans_of("14:00-18:00", "08:00-10:00", "09:00-11:00")
        self.assertEqual(find_gaps(worked, self.hours), ["gap 11:00-14:00 (180 min)"])

    def test_span_starting_early_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans_of("07:59-12:00"), self.hours)

    def test_span_ending_late_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans_of("12:00-18:01"), self.hours)
